import path from "node:path";

/**
 * Where a file a crew mate made lives, among the crew's folders on this computer (the open-source edition): the lane's own folder
 * first, then every other agent's here, then each crew mate's own folder and projects. A file is read from where it is, not only
 * from the folder of the lane it was named in: Sage saving to its own folder while it worked in a project, a teammate's file named
 * in the room, a path written out whole, all read "not found" (Arun, 2026-11-15: "make sure in crew rooms i can see every file
 * ... generated by all of the crew mates and it wont show up as not found file").
 *
 * A whole path is taken only inside one of those folders, the deepest that holds it; a relative one is looked for in each in turn.
 * Nothing outside them is read, and nothing with ".." in it.
 */
export async function crewFileAt(roots: readonly string[], want: string, exists: (p: string) => Promise<boolean>): Promise<{ root: string; rel: string } | null> {
  const clean = [...new Set(roots.filter(Boolean).map((r) => path.resolve(r)))];
  const name = want.trim().replace(/^~(?=$|[\\/])/, process.env.HOME ?? "~");
  if (!name || name.split(/[\\/]/).includes("..")) return null;
  if (path.isAbsolute(name)) {
    const full = path.resolve(name);
    const root = clean.filter((r) => full.startsWith(r + path.sep)).sort((a, b) => b.length - a.length)[0];
    return root && (await exists(full)) ? { root, rel: path.relative(root, full) } : null;
  }
  const rel = name.replace(/^\.[\\/]/, "");
  for (const root of clean) if (await exists(path.join(root, rel))) return { root, rel };
  return null;
}
